#!/usr/bin/env bash
set -Eeuo pipefail
umask 077
[[ $EUID == 0 && $(uname -s) == Linux && $(uname -m) == x86_64 ]] || { echo 'Run as root on Linux amd64'; exit 1; }
python3 -c 'import cryptography' 2>/dev/null || {
 apt-get update
 DEBIAN_FRONTEND=noninteractive apt-get install -y --no-upgrade python3 python3-cryptography
}
work=$(mktemp -d /var/tmp/ultrafull-commercial.XXXXXXXX)
chmod 700 "$work"
trap 'rm -rf -- "$work"' EXIT
cat > "$work/bootstrap.py" <<'ULTRAFULL_PYTHON'
import base64,json,pathlib,sys,os
root=pathlib.Path(__file__).resolve().parent
bundle=root/'bootstrap.zip';bundle.write_bytes(base64.b64decode(''))
sys.path.insert(0,str(bundle))
(root/'edition.json').write_text(json.dumps({'product': 'ULTRAFULL', 'version': '0.2.0', 'authority': 'https://ultraradar.ultranec.pro:9448', 'verify_key': 'f73170b1de1eb7c0b04e6abae68a5587f1f6d6fdbd76747c56ae5c9fb8072ce9'}))
from ufcommercial import client
from ufcommercial.common import STATE,load
client.APP=root
try:
 config=load(STATE/'activation.json')
 if config:client.refresh(config,{'product': 'ULTRAFULL', 'version': '0.2.0', 'authority': 'https://ultraradar.ultranec.pro:9448', 'verify_key': 'f73170b1de1eb7c0b04e6abae68a5587f1f6d6fdbd76747c56ae5c9fb8072ce9'})
 else:client.activate()
except (FileNotFoundError,ValueError):client.activate()
from ufcommercial.updater import fetch_release
stage=fetch_release({'product': 'ULTRAFULL', 'version': '0.2.0', 'authority': 'https://ultraradar.ultranec.pro:9448', 'verify_key': 'f73170b1de1eb7c0b04e6abae68a5587f1f6d6fdbd76747c56ae5c9fb8072ce9'},folder=root/'download')
os.execvp('bash',['bash',str(stage/'setup.sh')])

ULTRAFULL_PYTHON
python3 "$work/bootstrap.py"
